        let ways = 1;
        if (arr[i] > 0) {
            const info
                = maxLen(0, mx, 0, arr[i] - 1, 0, tree);
            if (info[0] + 1 > mxLen) {
                mxLen = info[0] + 1;
                ways = info[1];
            }
        }
        update(0, mx, 0, arr[i], mxLen, ways, tree);
    }
    return tree[0][1];
}

